CREATE TABLE "AdminNotification" ("id" TEXT PRIMARY KEY,"type" TEXT NOT NULL,"family" TEXT NOT NULL,"title" TEXT NOT NULL,"detail" TEXT NOT NULL,"country" TEXT,"city" TEXT,"href" TEXT NOT NULL,"dedupe_key" TEXT NOT NULL UNIQUE,"reminder" BOOLEAN NOT NULL DEFAULT false,"quantity" INTEGER NOT NULL DEFAULT 1,"occurred_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AdminNotification_occurred_at_id_idx" ON "AdminNotification"("occurred_at" DESC,"id" DESC);
CREATE INDEX "AdminNotification_family_country_occurred_at_idx" ON "AdminNotification"("family","country","occurred_at" DESC);
CREATE TABLE "AdminNotificationRead" ("notification_id" TEXT NOT NULL REFERENCES "AdminNotification"("id") ON DELETE CASCADE ON UPDATE CASCADE,"admin_id" TEXT NOT NULL REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE,"read_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("notification_id","admin_id"));
CREATE INDEX "AdminNotificationRead_admin_id_idx" ON "AdminNotificationRead"("admin_id");
CREATE FUNCTION bloodnet_admin_event() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE n jsonb:=to_jsonb(NEW); o jsonb:='{}'; fields text[]:=string_to_array(TG_ARGV[3],','); watched text; changed boolean:=false; region text; town text; kind text:=TG_ARGV[0]; event_id text; key text;
BEGIN
 IF TG_OP='DELETE' THEN n:=to_jsonb(OLD);o:=n; END IF;
 IF TG_OP='UPDATE' THEN o:=to_jsonb(OLD); FOREACH watched IN ARRAY fields LOOP IF (n->watched) IS DISTINCT FROM (o->watched) THEN changed:=true; END IF; END LOOP; IF NOT changed THEN RETURN NEW; END IF; END IF;
 IF TG_TABLE_NAME IN ('HomepageContent','PublicPageContent','ServiceAvailability') AND TG_OP<>'DELETE' AND NULLIF(n->'live','null'::jsonb) IS NOT DISTINCT FROM NULLIF(o->'live','null'::jsonb) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='RegionalPageContent' AND NOT COALESCE((n->>'published')::boolean,false) AND NOT COALESCE((o->>'published')::boolean,false) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='Blog' AND TG_OP='UPDATE' AND COALESCE(n->>'status','')<>'PUBLISHED' AND (n->>'status') IS NOT DISTINCT FROM (o->>'status') THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='AuthRiskEvent' AND COALESCE(n->>'event_type','') NOT IN ('ADMIN_USER_RESTRICTED','USER_RESTRICTED','RESTRICTED_IDENTITY','ADMIN_LOGIN_EMAIL_CHANGED') THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='Prescription' AND TG_OP='UPDATE' THEN
 IF n->>'email_status'='RETRY' THEN kind:='prescription.email.retry';
 ELSIF n->>'email_status'='SENT' AND EXISTS(SELECT 1 FROM public."AdminNotification" WHERE dedupe_key='prescription:'||(n->>'id')||':prescription.email.retry') THEN kind:='prescription.email.recovered';
 ELSE RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME='HomepageSlider' AND COALESCE(n->>'status','')<>'ACTIVE' AND COALESCE(o->>'status','')<>'ACTIVE' THEN RETURN NEW; END IF;
 region:=COALESCE(NULLIF(n->>'location_country',''),NULLIF(n->>'country',''));town:=COALESCE(NULLIF(n->>'location_city',''),NULLIF(n->>'city',''));
 IF TG_TABLE_NAME='Blog' AND n->>'author_type'='USER' THEN SELECT location_country,location_city INTO region,town FROM public."User" WHERE id=n->>'author_id'; END IF;
 IF region IS NULL AND n->>'user_id' IS NOT NULL THEN SELECT location_country,location_city INTO region,town FROM public."User" WHERE id=n->>'user_id'; END IF;
 IF kind NOT LIKE 'prescription.email.%' THEN kind:=kind||CASE WHEN TG_OP='INSERT' THEN '.created' WHEN TG_OP='DELETE' THEN '.removed' ELSE '.updated' END; END IF;
 key:='db:'||COALESCE(NULLIF(current_setting('bloodnet.notification_batch',true),''),transaction_timestamp()::text||':'||txid_current())||':'||TG_TABLE_NAME||':'||kind||':'||COALESCE(region,'global');
 IF kind LIKE 'prescription.email.%' THEN key:='prescription:'||(n->>'id')||':'||kind; IF EXISTS(SELECT 1 FROM public."AdminNotification" WHERE dedupe_key=key) THEN RETURN NEW; END IF; END IF;
 INSERT INTO public."AdminNotification"(id,type,family,title,detail,country,city,href,dedupe_key) VALUES(gen_random_uuid()::text,kind,TG_ARGV[1],TG_ARGV[2],CASE WHEN TG_OP='INSERT' THEN '1 record added. Open the workspace to review.' WHEN TG_OP='DELETE' THEN '1 record removed. The original destination may no longer exist.' ELSE '1 record changed. Open the workspace to review.' END,region,town,'/private/console-0be5626d4305f192e37e/workspace'||TG_ARGV[4],key) ON CONFLICT(dedupe_key) DO UPDATE SET quantity="AdminNotification".quantity+1,detail=("AdminNotification".quantity+1)::text||' records changed in one operation. Open the workspace to review.',city=NULL;
 RETURN NEW;
END $$;
CREATE TRIGGER bloodnet_admin_event AFTER INSERT OR UPDATE OR DELETE ON "User" FOR EACH ROW EXECUTE FUNCTION bloodnet_admin_event('account','registration','Account registration or donor status','is_active_donor,verification_status,blood_group,location_city,location_country','/users');
