INSERT INTO "AdminNotification"(id,type,family,title,detail,country,city,href,dedupe_key,reminder,occurred_at) SELECT gen_random_uuid()::text,'pending.reminder','report','Existing pending work: Report','Initial reminder, not a new submission. Review the existing queue.',COALESCE(to_jsonb(r)->>'location_country',to_jsonb(r)->>'country'),NULL,'/private/console-0be5626d4305f192e37e/workspace/reports','initial:Report:'||(to_jsonb(r)->>'id'),true,COALESCE((to_jsonb(r)->>'created_at')::timestamp,CURRENT_TIMESTAMP) FROM "Report" r WHERE COALESCE(to_jsonb(r)->>'status',to_jsonb(r)->>'review_status','') IN ('PENDING','UNDER_REVIEW') ON CONFLICT(dedupe_key) DO NOTHING;
