CREATE TABLE "MaintenanceGate" ("id" INTEGER PRIMARY KEY DEFAULT 1 CHECK(id=1),"paused" BOOLEAN NOT NULL DEFAULT false);
INSERT INTO "MaintenanceGate"(id,paused) VALUES(1,false);
CREATE FUNCTION bloodnet_maintenance_write_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public."MaintenanceGate" WHERE id=1 AND paused) THEN
  IF TG_TABLE_NAME='Prescription' AND TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['email_status','email_attempts','email_next_attempt_at','email_locked_until','email_sent_at']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['email_status','email_attempts','email_next_attempt_at','email_locked_until','email_sent_at']) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='AdminUser' AND TG_OP='UPDATE' AND (to_jsonb(NEW)-'last_login') IS NOT DISTINCT FROM (to_jsonb(OLD)-'last_login') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Software Under Maintenance; retry this write later.' USING ERRCODE='55000';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
DO $$ DECLARE item record; BEGIN FOR item IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename NOT IN ('_prisma_migrations','MaintenanceGate','AdminNotification','AdminNotificationRead','AuthRiskEvent') LOOP EXECUTE format('CREATE TRIGGER bloodnet_maintenance_write_guard BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION bloodnet_maintenance_write_guard()',item.tablename); END LOOP; END $$;
